static inline ut32 r_buf_read_be32_at(RBuffer *b, ut64 addr) { /* <=== r_buf_read_be32_at */ 
	ut8 buf[sizeof (ut32)];
	int r = (int) r_buf_read_at (b, addr, buf, sizeof (buf));
	return r == sizeof (buf)? r_read_be32 (buf): UT32_MAX;
}

